#!/usr/bin/env python3
"""Append the seventh manually reviewed full-answer batch (ANS-176 through ANS-200)."""
from __future__ import annotations
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];PATH=ROOT/'content'/'answer-layers.json';DATE='2026-08-15'
def L(i,t,q,s,m,a,tr,f):return {'id':f'ANS-{i:03d}','topic':t,'question':q,'shortAnswer':s,'modelAnswer':m,'assumptions':a,'traps':tr,'followUps':f,'reviewedOn':DATE,'status':'reviewed-full-v1'}
B=[
L(176,'Observational Astronomy','What physical quantities does a telescope–detector system measure?','It measures detector counts, charge, or digital values produced by radiation over angle, wavelength, polarization, and time; calibration maps these to radiance, flux, position, or spectra with uncertainty.','The telescope collects and transforms an incident electromagnetic field through an aperture, optics, filters or spectrograph; the detector converts absorbed photons to an electrical signal. The raw output is convolved with throughput, point/line-spread function, pixel response, exposure, sampling, background, noise, and atmosphere where relevant. It does not directly measure “temperature,” “composition,” or “distance.” Those are inferred through calibrated physical models, standards, metadata, and uncertainty.', ['Instrument mode, passband and exposure defined','Optical/detector response and calibration available'],['Calling an image pixel direct source brightness','Treating an inferred property as a detector observable'],['Counts versus flux?','What is throughput?','Why PSF matters?','How background is removed?','Which calibration standard?']),
L(177,'Observational Astronomy','What is seeing?','Astronomical seeing is atmospheric-turbulence blurring and image motion, often summarized by a long-exposure angular PSF width at a stated wavelength and airmass.','Refractive-index fluctuations along the line of sight distort the incoming wavefront. Over an exposure they broaden the stellar image and can dominate a ground telescope’s diffraction scale. Seeing varies with wavelength, zenith angle, altitude, turbulence profile, dome conditions, and exposure; FWHM alone does not describe every effect. It is distinct from transparency and from telescope aberration. Site monitors, guide stars, and PSF measurements quantify it.', ['Ground-based optical observation through atmosphere','Wavelength, exposure and angular metric specified'],['Calling poor transparency bad seeing','Quoting seeing without wavelength or conditions'],['What is Fried parameter?','Why wavelength dependence?','Seeing versus diffraction?','How measure PSF?','What can adaptive optics correct?']),
L(178,'Stellar Astrophysics','How do you estimate stellar temperature?','Estimate effective temperature from calibrated spectra or multi-band colours using a justified atmosphere/extinction model; Wien’s law is only a first blackbody approximation.','A continuum shape or colour index changes with temperature, but opacity, metallicity, gravity, reddening, filter response and calibration create degeneracies. Spectral-line ratios or excitation/ionization balance can add constraints, again through atmosphere models. Effective temperature is defined by total emergent flux, L=4πR²σT_eff⁴, not necessarily a local gas temperature. I would use multiple diagnostics, account for extinction, and report model/systematic uncertainty.', ['Photometric/spectroscopic calibration and extinction treatment','Stellar atmosphere model appropriate'],['Assigning exact temperature from visual colour','Using one blackbody peak while ignoring opacity/reddening'],['What is effective temperature?','How dust biases colour?','Which line ratio?','Role of metallicity?','How validate estimate?']),
L(179,'Observational Astronomy','What is a detector pixel scale?','Pixel scale is the angle on sky represented per detector pixel, set by pixel pitch and effective focal length plus distortion; it is sampling, not automatically angular resolution.','For small angles an ideal plate scale is approximately p/f radians per pixel. Real systems need an astrometric solution for distortion, alignment, binning and wavelength dependence. To sample a point-spread function without losing information, multiple pixels across its width are generally needed under a stated sampling criterion. Smaller angular pixels can oversample without improving optical/seeing-limited resolution and reduce photons per pixel.', ['Paraxial small-angle relation for p/f','Effective focal length and detector geometry known'],['Equating pixel scale with resolved detail','Claiming smaller pixels always improve sensitivity/resolution'],['Compute plate scale.','What is Nyquist sampling?','How distortion calibrated?','Binning effect?','PSF versus pixel scale?']),
L(180,'Adaptive Optics','Why use adaptive optics?','Adaptive optics senses time-varying wavefront error and drives a corrective element to reduce atmospheric or system aberration, improving angular concentration within bandwidth and field limits.','A guide source and wavefront sensor estimate distortions; a control loop commands a deformable mirror. Performance depends on turbulence strength/profile, guide-star brightness and separation, correction order, latency, noise, fitting error, wavelength, anisoplanatism and telescope optics. It does not remove cloud extinction, photon noise, all speckles, or unlimited field aberration. Laser guide stars also need separate tip–tilt and operational considerations.', ['Wavefront disturbance within controllable temporal/spatial bandwidth','Guide source and calibration available'],['Saying adaptive optics makes every image diffraction limited','Ignoring anisoplanatism and control delay'],['What does wavefront sensor measure?','Why deformable mirror?','What is guide star?','What is Strehl ratio?','Main error terms?']),
L(181,'Detectors','How do you reduce detector noise?','Identify the dominant noise source, then reduce it through photon collection, cooling, bandwidth/exposure choice, low-noise electronics, shielding/grounding, calibration, and averaging only where independence and stability hold.','Photon shot noise is fundamental for a given count, while dark current often falls with cooling; read noise can be reduced by electronics and readout strategy; background requires optical/spatial/temporal control and subtraction; 1/f, pickup, drift and quantization need different remedies. Increasing exposure can improve signal-to-noise until saturation, cosmic events, motion or drift dominate. I would build a noise budget in physical units and validate it using darks, flats, repeated data and frequency/time analysis.', ['Signal and noise bandwidth/exposure defined','Detector linearity and operating point controlled'],['Calling all noise random and removable by averaging','Cooling without checking condensation, power or dark-current regime'],['Shot versus read noise?','Why cooling helps?','How bandwidth enters?','What is dark frame?','How validate noise model?']),
L(182,'Solar Physics','What physical processes shape the observed solar spectrum?','The observed solar spectrum combines photospheric thermal continuum and opacity, atomic/molecular lines, velocities, magnetic splitting, chromospheric/coronal emission, atmosphere and instrument response.','The visible continuum is broadly thermal but wavelength-dependent opacity sets where radiation escapes. Absorption lines form through element abundance, excitation, ionization and radiative transfer in cooler overlying layers; velocity shifts/broadens lines and magnetic fields can split/polarize them. UV, EUV, X-ray and radio bands sample different plasma and mechanisms. Earth atmosphere, scattered light, resolution and calibration shape the measured spectrum, so a line is interpreted through a model rather than as a direct composition label.', ['Solar region, wavelength and observation geometry specified','Instrument/atmosphere calibrated'],['Calling the solar spectrum a perfect blackbody','Assigning line strength to abundance alone'],['Why absorption lines?','What sets continuum?','How Doppler enters?','What is Zeeman effect?','Why multi-wavelength?']),
L(183,'Solar Physics','What is a solar flare?','A solar flare is a rapid release of magnetic energy in the solar atmosphere that heats plasma, accelerates particles, and enhances electromagnetic emission across bands.','Magnetic reconnection is a leading framework for converting stored magnetic energy, but the observed event includes complex particle transport, radiation and plasma response. Flares are classified from specified observations; they are distinct from coronal mass ejections, though events can be associated. Spacecraft impact depends on electromagnetic radiation, energetic particles, geometry and subsequent solar-wind structures. Current flare status must come from official monitoring, not memory.', ['Public conceptual solar-physics scope','Observed band/classification and geometry specified'],['Equating every flare with a CME','Claiming one flare class determines all Earth effects'],['What is reconnection?','Flare versus CME?','Which wavelengths brighten?','How particles accelerate?','How monitor flare?']),
L(184,'Heliophysics','How does the solar wind affect Earth?','The solar wind carries plasma and magnetic field that interact with Earth’s magnetosphere, driving compression, reconnection, currents, aurora and—under suitable conditions—geomagnetic disturbance.','The impact depends strongly on solar-wind speed, density and magnetic-field orientation, not speed alone. Energy and momentum transfer alter magnetopause position, magnetotail and radiation-belt/ionospheric conditions. Consequences can include navigation/communication errors, satellite charging, drag changes through upper-atmosphere heating, and geomagnetically induced currents. Forecasts are probabilistic and current operational claims require official space-weather data.', ['Magnetized plasma interaction framework','Current event data excluded unless officially checked'],['Calling solar wind ordinary neutral wind','Saying southward field always gives a fixed storm outcome'],['What is magnetopause?','Why IMF orientation matters?','How aurora forms?','Effect on satellites?','How measured upstream?']),
L(185,'Space Weather','What is space weather?','Space weather describes variable solar, heliospheric, magnetospheric and ionospheric conditions that can affect space- and ground-based technology and operations.','Drivers include solar electromagnetic eruptions, energetic particles and solar-wind structures. Effects differ in onset and coupling: radiation dose and single-event effects, charging, GNSS/communication propagation changes, sensor backgrounds, atmospheric drag and induced currents. A useful answer connects a specific driver to a physical chain, monitored quantity, uncertainty and mitigation. Current alerts, indices and mission impacts must be verified from official services.', ['Specific driver, region and technology identified','Operational statements source-current'],['Using space weather as a synonym for terrestrial weather','Treating one index as universal hazard'],['Main drivers?','How ionosphere responds?','Charging mechanism?','Why LEO drag?','Where verify alerts?']),
L(186,'Space Product Engineering','What makes a satellite product useful?','A satellite product is useful when a validated observable or service meets a real user decision with adequate accuracy, latency, coverage, reliability, interfaces, cost and documented limitations.','I would begin with the user action, not the satellite. The chain includes mission geometry, payload measurement, calibration, downlink, processing, retrieval, uncertainty, validation, delivery format and operational support. A high-resolution image is not useful if it arrives too late, lacks ground truth, has uncontrolled bias or cannot integrate into workflow. Success metrics and failure thresholds should be agreed before optimizing hardware.', ['User decision and acceptance metric defined','End-to-end measurement/service chain available'],['Equating more data with user value','Ignoring latency, uncertainty and integration'],['Who is user?','What observable?','How validate?','What latency?','What failure threshold?']),
L(187,'Payload Systems','How do you choose a payload?','Translate mission objective into an observable and performance/error budget, then trade candidate payloads against orbit, coverage, calibration, mass, power, thermal, pointing, data, reliability, cost and schedule.','The payload should be selected because its interaction physics and sensitivity can answer the mission question. I would quantify spectral/spatial/temporal/radiometric or other requirements, backgrounds and validation. Then I would evaluate bus interfaces, environmental/contamination needs, technology maturity, testability, downlink and processing. A heritage instrument is not automatically appropriate, and the highest specification can be unaffordable or unnecessary.', ['Mission objective and measurable success criteria defined','Candidate technologies compared under common conditions'],['Choosing payload from one headline specification','Ignoring bus/ground/data interfaces'],['What is observable?','Which error dominates?','How orbit affects choice?','What calibration needed?','What prototype retires risk?']),
L(188,'Mission Engineering','What is the difference between a demonstration and a mission?','A demonstration proves a bounded capability; a mission must deliver defined objectives through an end-to-end, reliable and operational system over stated conditions and duration.','A technology demo may use limited geometry, manual support, tolerant schedule or partial success criteria. A mission adds stakeholder requirements, complete interfaces, launch/orbit/ground/operations, calibration, data products, safe modes, reliability, lifecycle and disposal. Demonstration evidence can retire uncertainty but does not establish production repeatability or operational availability. The boundary and success criteria should be explicit.', ['Demonstrated capability and mission objective specified','Lifecycle and operational context defined'],['Calling one successful test a mission-ready service','Dismissal of demos despite bounded evidence value'],['What is success criterion?','How scale operations?','What reliability evidence?','Ground segment role?','When demo is enough?']),
L(189,'Spacecraft Budgets','How do you manage mass and power?','Create controlled allocations, margins and time/mode-dependent budgets; trace every change through subsystem interfaces and verify estimates with analysis and test.','Mass budget includes hardware, harness, fluids, adapters, uncertainty and growth allowance with centre-of-mass/inertia implications. Power budget must distinguish average, peak, startup, eclipse, degradation and operational modes, tied to generation, storage, distribution and thermal dissipation. Margin is not spare value to spend twice. Configuration control, design reviews, measurement and sensitivity/trade analysis keep budgets credible.', ['Mission modes and design maturity defined','Common reference configuration used'],['Using only average power','Double-counting margin or omitting harness/adapters'],['Peak versus average?','How eclipse changes budget?','What is growth allowance?','How mass affects launch/orbit?','How verify budget?']),
L(190,'Sensor Validation','How would you design a sensor test?','Start from measurand and requirement, apply traceable controlled inputs across range and environment, include blanks/interferents/repeats, and predefine accuracy, sensitivity, drift and failure criteria.','I would map each requirement to a verification method and reference with lower known uncertainty. Test points should cover nominal and boundary conditions, up/down cycles for hysteresis, randomized order for drift, cross-sensitivities, response time, noise, saturation and recovery. Configuration and raw data must be preserved; independent validation points prevent fitting and testing on the same data. Safety and environmental facilities remain procedure-controlled.', ['Measurand, range and environment defined','Suitable traceable reference and safe facility'],['Testing only nominal points','Calling calibration alone selectivity validation'],['What is control?','How test hysteresis?','Which uncertainty ratio?','How test drift?','Acceptance criterion?']),
L(191,'Payload Qualification','What makes a payload space-ready?','A payload is space-ready only when the integrated measurement function and interfaces satisfy controlled requirements with calibration, environmental, reliability, software/data and operational evidence.','Readiness covers optics/sensor/electronics, structure, thermal, power, command/data, pointing/time, contamination, EMC, radiation and launch loads under the applicable programme. The exact qualification/acceptance flow is standard- and mission-specific. Calibration must survive or be recoverable after environments, anomalies and safe modes must be handled, and ground processing/validation must be ready. A component datasheet or bench image is not system readiness.', ['Mission requirements and applicable standards defined','Flight-representative configuration under control'],['Calling environmental survival measurement performance','Ignoring ground processing and in-orbit calibration'],['Which environments?','How verify interface?','Qualification versus acceptance?','What is calibration transfer?','How safe mode affects payload?']),
L(192,'Detector Trade Studies','How would you decide which detector specification matters most?','Start from the mission observable and error budget; select the detector parameter that dominates required information or risk under actual flux, bandwidth, temperature and integration conditions.','Quantum efficiency, responsivity, dark/read noise, dynamic range, full well, pixel size, spectral response, bandwidth, radiation tolerance and stability trade against each other. For faint flux, total SNR may dominate; for imaging, MTF/sampling and uniformity matter; for fast transients, bandwidth/dead time; for space, environment and calibration stability. I would propagate candidates through an end-to-end model and validate the dominant unknown rather than rank datasheet maxima.', ['Mission signal/background and operating point known','Candidate specifications measured under comparable conditions'],['Choosing highest quantum efficiency universally','Comparing datasheets at different temperatures/bandwidths'],['What dominates SNR?','Pixel size trade?','How dynamic range matters?','Which environment test?','What prototype test?']),
L(193,'Materials Screening','How do you screen a material quickly?','Define the must-meet property and fastest safe discriminating tests, use references and controls, and reject only against predeclared criteria while preserving evidence.','I would begin with application constraints such as phase, composition, conductivity, optical response, thermal stability, adhesion or environment. Low-cost checks may include visual/mass/dimension inspection, a reference structural or spectroscopic measurement, simple property coupon and accelerated but representative condition. The screen must have sensitivity, calibration and false-reject awareness. Passing is not qualification; it only prioritizes deeper characterization.', ['Application requirement and rejection threshold defined','Safe sample handling and suitable reference'],['Running every available technique without decision logic','Calling a fast screen proof of long-term reliability'],['Which property first?','What reference?','How avoid false reject?','What next test after pass?','What if screen conflicts?']),
L(194,'Materials Scale-up','What is a scale-up problem?','Scale-up is failure of laboratory process/evidence to remain uniform, controllable, safe, economical and reproducible when batch size, geometry, equipment or throughput changes.','Heat and mass transfer, mixing, diffusion length, nucleation, atmosphere, gradients, residence time, contamination, tooling and measurement sampling can change nonlinearly with scale. Equipment may impose different boundary conditions and control authority. I would identify dimensionless/regime changes, instrument representative locations, run staged batches, track yield and variance, and update hazards. Multiplying reagent quantities is not a scale-up model.', ['Laboratory process and target scale specified','Material/energy balances and safety reviewed'],['Assuming linear parameter scaling','Comparing one large batch to one small batch'],['Which gradient dominates?','How mixing scales?','What is pilot scale?','How sample large batch?','What new hazard?']),
L(195,'Materials Reliability','How do you test material reliability?','Define failure modes and use representative coupons/components under mission loads and environments with controls, monitoring, statistics, and predeclared acceptance criteria.','Reliability is application-specific: thermal cycling, vacuum/outgassing, radiation, humidity, corrosion, vibration, fatigue, creep, wear or electrical/optical drift may matter. Accelerated tests require a justified acceleration model and must not introduce an irrelevant failure. I would measure initial state, monitor degradation, include references and batch/position variation, inspect failure mechanisms, and correlate tests with models. One surviving sample is not a reliability demonstration.', ['Application environment and lifetime defined','Failure criterion and acceleration model specified'],['Calling harshest possible test representative','Ignoring sample count and failure mechanism'],['What failure mode first?','How accelerate safely?','How many specimens?','What is censoring?','How correlate model/test?']),
L(196,'Earth Observation Products','How can satellite data become a product?','Convert calibrated observations into a validated, documented output that answers a repeatable user decision with known uncertainty, latency, provenance, interfaces and support.','The pipeline goes from acquisition and metadata through radiometric/geometric correction, quality flags, retrieval/model, ground truth, uncertainty and versioned delivery. Product design includes user requirements, spatial/temporal coverage, service availability, API/file standards, monitoring for sensor/model drift and feedback. A machine-learning score or attractive map is not a product without generalization tests, decision thresholds and lifecycle ownership.', ['User workflow and observable defined','Calibration, labels and validation representative'],['Equating algorithm output with decision truth','Ignoring version/provenance and model drift'],['Who validates?','What ground truth?','Which uncertainty?','How monitor drift?','What is service metric?']),
L(197,'Data Analysis','How would you handle a noisy dataset?','Preserve raw data, characterize signal and noise sources in time/frequency and by condition, validate calibration, then choose a physical model or filter without hiding uncertainty.','I would inspect distributions, time order, spectra, missingness, saturation, backgrounds, repeats and controls. Noise may be photon/counting, electronic, environmental, drift, interference or model mismatch; each needs different action. Filtering must be declared and tested for bias or signal distortion. I would avoid deleting points without criteria, quantify sensitivity to preprocessing, compare independent data, and report when SNR is insufficient for the claim.', ['Measurand and expected signal timescale/spectrum defined','Raw data and metadata preserved'],['Smoothing until the expected trend appears','Calling structured residual noise'],['How estimate SNR?','What filter bias?','How detect drift?','When average helps?','When conclude insufficient?']),
L(198,'Product Prototyping','What is a minimum viable prototype?','It is the smallest safe, testable implementation that can answer the highest-value uncertainty about user need, physics, interface or performance—not the smallest impressive demo.','I would state the decision and competing hypotheses, then include only functions needed to produce discriminating evidence. A benchtop proxy, simulation plus coupon, breadboard or limited pipeline may suffice. It needs instrumentation, calibration, success/failure criteria and configuration records. “Viable” refers to learning for the next decision, not flight or production readiness; the prototype should expose rather than hide dominant risk.', ['Decision uncertainty and user/requirement defined','Safety and evidence quality nonnegotiable'],['Building many features before testing risk','Calling MVP flight-ready'],['What decision?','Which feature omitted?','What measurement?','Failure criterion?','What comes next?']),
L(199,'Interface Engineering','How do you document an interface?','Use a controlled interface specification defining functions, physical/electrical/data/thermal/timing properties, units, tolerances, ownership, states, errors, verification and change history.','For a sensor or payload I would record connectors/pinout, voltage/current/transients, grounding, protocol, data schema/endian/time tags, mechanical datums/loads, thermal paths, pointing/alignment, command/state behavior, fault response and environmental limits. Both sides must use the same revision and assumptions. Interface tests and responsibility matrices reduce gaps. A diagram without limits or version control is not sufficient.', ['Two interfacing configurations and owners defined','Units, coordinate frames and revisions controlled'],['Documenting only nominal values','Changing one side without impact review'],['What is ICD?','How verify timing?','How handle tolerance?','Who owns error?','What if interface changes?']),
L(200,'Aerospace Testing','Difference between qualification and acceptance testing?','Qualification demonstrates a design can withstand required environments with margin; acceptance screens each delivered item for workmanship/performance under controlled, generally less severe conditions.','Qualification is usually performed on a representative configuration to establish design adequacy against programme requirements and margins. Acceptance testing is applied to flight/delivered units to detect workmanship defects and confirm baseline function without consuming excessive life. Protoflight or other strategies combine elements under specific standards and risk decisions. Exact levels, durations and sequence are programme-specific; neither term means an arbitrary harsh test.', ['Applicable programme standard and hardware model defined','Configuration differences traceable'],['Calling acceptance a repeat of full qualification universally','Assuming qualification of one design covers uncontrolled changes'],['What is protoflight?','Why acceptance lower?','What is workmanship?','How changes trigger requalification?','Which functional tests bracket environments?'])]
def main():
 d=json.loads(PATH.read_text());base=[x for x in d['layers'] if int(x['id'].split('-')[1])<176];later=[x for x in d['layers'] if int(x['id'].split('-')[1])>200];assert len(base)==175;d['layers']=sorted(base+B+later,key=lambda x:int(x['id'].split('-')[1]));assert len(B)==25 and len(d['layers'])==200+len(later) and len({x['id'] for x in d['layers']})==len(d['layers']);PATH.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');print(f"Wrote answer batch 7; total reviewed layers: {len(d['layers'])}")
if __name__=='__main__':main()
